        #[test]
        fn parliament_candidate_snapshot_derivation_has_preallocation_resource_bounds() {
            assert!(
                ensure_parliament_citizen_registry_capacity_with_limit_v1(2, true, 2).is_ok(),
                "an existing citizen may top up at the cardinality ceiling"
            );
            let capacity_error =
                ensure_parliament_citizen_registry_capacity_with_limit_v1(2, false, 2)
                    .expect_err("a new citizen must not exceed the registry ceiling");
            assert!(
                format!("{capacity_error:?}").contains("citizen registry reached"),
                "unexpected capacity error: {capacity_error:?}"
            );

            let state = blank_test_state();
            let header = first_test_block_header();
            let mut block = state.block(header);
            let mut state_transaction = block.transaction();
            state_transaction.gov.citizenship_bond_amount = Quantity::zero();
            let mut expected = vec![
                parliament_test_account(0xD3),
                parliament_test_account(0xD1),
                parliament_test_account(0xD2),
            ];
            for candidate in &expected {
                state_transaction.world.citizens.insert(
                    candidate.clone(),
                    crate::state::CitizenshipRecord {
                        owner: candidate.clone(),
                        amount: Quantity::zero(),
                        bonded_height: 1,
                    },
                );
            }

            let registry_error = canonical_parliament_eligible_candidates_with_limits_v1(
                &state_transaction,
                2,
                usize::MAX,
            )
            .expect_err("the registry count must be checked before candidate collection");
            assert!(
                format!("{registry_error:?}").contains("citizen registry exceeds"),
                "unexpected registry-bound error: {registry_error:?}"
            );

            let byte_error = canonical_parliament_eligible_candidates_with_limits_v1(
                &state_transaction,
                3,
                norito::core::seq_len_prefix_len(0),
            )
            .expect_err("the first candidate must exceed an empty-sequence-only byte budget");
            assert!(
                format!("{byte_error:?}").contains("snapshot exceeds"),
                "unexpected snapshot-bound error: {byte_error:?}"
            );

            expected.sort_unstable();
            let exact_snapshot_bytes = norito::core::encoded_payload_len(&expected)
                .expect("measure the canonical candidate snapshot payload");
            assert_eq!(
                canonical_parliament_eligible_candidates_with_limits_v1(
                    &state_transaction,
                    3,
                    exact_snapshot_bytes,
                )
                .expect("bounded complete candidate snapshot"),
                expected,
                "resource admission must preserve the complete canonical electorate"
            );
            let exact_byte_error = canonical_parliament_eligible_candidates_with_limits_v1(
                &state_transaction,
                3,
                exact_snapshot_bytes - 1,
            )
            .expect_err("the canonical byte cap must be exact");
            assert!(
                format!("{exact_byte_error:?}").contains("snapshot exceeds"),
                "unexpected exact byte-bound error: {exact_byte_error:?}"
            );
        }

        #[test]
        fn parliament_confirmation_candidates_exclude_policy_jury_members() {
            let policy_member = AccountId::new(checked_keypair().public_key().clone());
            let first_disjoint = AccountId::new(checked_keypair().public_key().clone());
            let second_disjoint = AccountId::new(checked_keypair().public_key().clone());
            let election_attempt_id =
                iroha_data_model::governance::types::BodyElectionAttemptId::new([0x93; 32]);
            let policy_assignments = vec![
                iroha_data_model::governance::types::ParliamentSeatAssignmentV1 {
                    assignment_id: iroha_data_model::governance::types::AssignmentId::derive_v1(
                        election_attempt_id,
                        &policy_member,
                    ),
                    member: policy_member.clone(),
                },
            ];
            let mut candidates = vec![
                policy_member.clone(),
                first_disjoint.clone(),
                second_disjoint.clone(),
            ];
            candidates.sort_unstable();
            let mut expected = vec![first_disjoint, second_disjoint];
            expected.sort_unstable();

            assert_eq!(
                confirmation_candidate_snapshot_v1(candidates, &policy_assignments),
                expected
            );
            assert!(
                confirmation_candidate_snapshot_v1(
                    vec![policy_member.clone()],
                    &policy_assignments
                )
                .is_empty(),
                "Policy Jury members must not contribute Confirmation capacity"
            );
            assert_eq!(
                confirmation_candidate_snapshot_v1(
                    vec![policy_member, expected[0].clone()],
                    &policy_assignments,
                ),
                vec![expected[0].clone()],
                "one disjoint candidate remains observable so narrow finalization can classify capacity objectively"
            );
        }

        #[test]
        fn narrow_confirmation_request_freezes_exact_current_snapshot_and_schedule() {
            let state = blank_test_state();
            let block = new_dummy_block_at_height(NonZeroU64::new(7).expect("nonzero height"));
            let mut state_block = state.block(block.as_ref().header());
            let mut state_transaction = state_block.transaction();
            let fixture = seed_parliament_permissionless_progress_fixture(
                &mut state_transaction,
                ParliamentPermissionlessProgressPhase::AwaitingPulse,
            );
            let attempt = state_transaction
                .world
                .parliament_attempts
                .get(&fixture.governance_attempt_id)
                .expect("retained Parliament attempt");
            let mut candidates = vec![
                parliament_test_account(0xE1),
                parliament_test_account(0xE2),
                parliament_test_account(0xE3),
            ];
            candidates.sort_unstable();
            let request_height = state_transaction.block_height();
            let request = canonical_confirmation_sortition_request_v1(
                attempt,
                &candidates,
                request_height,
                &state_transaction,
            )
            .expect("derive atomic Confirmation Jury request");

            assert_eq!(
                request.body_election_attempt_id,
                BodyElectionAttemptId::derive_v1(
                    fixture.governance_attempt_id,
                    ParliamentBody::ConfirmationJury,
                    0,
                )
            );
            assert_eq!(request.body, ParliamentBody::ConfirmationJury);
            assert_eq!(request.candidate_count, 3);
            assert_eq!(
                request.candidate_root,
                parliament_candidate_root_v1(
                    fixture.governance_attempt_id,
                    ParliamentBody::ConfirmationJury,
                    &candidates,
                )
            );
            assert_eq!(
                request.target_seats,
                u32::try_from(state_transaction.gov.confirmation_jury_size)
                    .expect("configured target fits u32")
            );
            assert_eq!(request.request_height, request_height);
            // The slot is the first consensus-native pulse height the frozen attempt
            // fields and the attempt's own generation history derive.
            assert_eq!(
                Some(request.pulse_height),
                attempt.next_sortition_generation_pulse_height_v1(
                    request_height,
                    BeaconSessionId::for_network_v1(&state_transaction.network_id),
                )
            );
            assert_eq!(
                (request.pulse_height + 1) % attempt.sortition_pulse_epoch_length_blocks(),
                0
            );
            assert!(
                request.pulse_height >= request_height + attempt.sortition_pulse_delay_blocks()
            );
            // Independent literal: the first native height at or after the delay and above
            // every earlier generation slot of the fixture, which a skipped boundary misses.
            assert_eq!(request.pulse_height, 13);
            assert_eq!(
                request.beacon_session_id,
                BeaconSessionId::for_network_v1(&state_transaction.network_id)
            );
            assert_eq!(request.id, request.canonical_id());
            assert!(
                canonical_confirmation_sortition_request_v1(
                    attempt,
                    &candidates[..1],
                    request_height,
                    &state_transaction,
                )
                .is_err(),
                "an atomic Confirmation request must never freeze an identity-mask electorate"
            );
        }

        #[test]
        fn parliament_head_root_is_stable_and_value_binding() {
            let first = parliament_governance_head_root_v1(&41_u64);
            assert_eq!(first, parliament_governance_head_root_v1(&41_u64));
            assert_ne!(first, parliament_governance_head_root_v1(&42_u64));
            assert_ne!(first, [0; 32]);
        }

        const PARLIAMENT_DUE_CERTIFICATE_HEIGHT: u64 = 60;

        #[derive(Clone)]
        struct DueParliamentCertificateFixture {
            proposal_id: [u8; 32],
            governance_attempt_id: GovernanceAttemptId,
            certificate: GovernanceCertificateV1,
        }

        fn parliament_test_root(tag: u8) -> [u8; 32] {
            [tag.max(1); 32]
        }

        fn parliament_test_account(tag: u8) -> AccountId {
            let keypair = KeyPair::try_from_seed(vec![tag.max(1); 32], Algorithm::Ed25519)
                .expect("derive deterministic Parliament world-test key");
            AccountId::new(keypair.public_key().clone())
        }

        fn parliament_test_candidates() -> Vec<AccountId> {
            let mut candidates = (1_u8..=24).map(parliament_test_account).collect::<Vec<_>>();
            candidates.sort_unstable();
            candidates
        }

        fn parliament_test_governance(
            requirements: &[RequiredParliamentBodyV1],
        ) -> iroha_config::parameters::actual::Governance {
            let mut governance = iroha_config::parameters::actual::Governance {
                parliament_alternate_size: 0,
                ..iroha_config::parameters::actual::Governance::default()
            };
            for requirement in requirements {
                match requirement.body {
                    ParliamentBody::RulesCommittee => governance.rules_committee_size = 3,
                    ParliamentBody::AgendaCouncil => governance.agenda_council_size = 3,
                    ParliamentBody::InterestPanel => governance.interest_panel_size = 3,
                    ParliamentBody::ReviewPanel => governance.review_panel_size = 3,
                    ParliamentBody::CoordinationCouncil => {
                        governance.coordination_council_size = 3;
                    }
                    ParliamentBody::MpcCommittee => governance.mpc_committee_size = 3,
                    ParliamentBody::FmaCommittee => governance.fma_committee_size = 3,
                    ParliamentBody::OversightCommittee => {
                        governance.oversight_committee_size = 3;
                    }
                    ParliamentBody::PolicyJury => governance.policy_jury_size = 3,
                    ParliamentBody::ConfirmationJury => governance.confirmation_jury_size = 3,
                }
            }
            governance
        }

        fn parliament_permissionless_progress_proposal() -> ProposalKind {
            ProposalKind::DeployContract(
                iroha_data_model::governance::types::DeployContractProposal {
                    proposal_operator: ALICE_ID.clone(),
                    contract_address:
                        "irohac1qyqqqqqqqqqqqq95fes93ygegsv5enq9mqsz6x4lv4vp9gg4yxgjw"
                            .parse()
                            .expect("permissionless-progress contract address"),
                    code_hash: ContractCodeHash::new([0x31; 32]),
                    abi_hash: ContractAbiHash::new([0x41; 32]),
                    abi_version: iroha_data_model::governance::types::AbiVersion::new(1),
                    manifest_provenance: None,
                },
            )
        }

        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum ParliamentPermissionlessProgressPhase {
            AwaitingPulse,
            Drawing,
            InvitationsOpen,
            InvitationsAccepted,
        }

        struct ParliamentPermissionlessProgressFixture {
            governance_attempt_id: GovernanceAttemptId,
            election_attempt_id: BodyElectionAttemptId,
            request_ids: Vec<iroha_data_model::governance::types::SortitionRequestId>,
            beacon_session_id: BeaconSessionId,
            pulse_height: u64,
            pulse_id: BeaconPulseId,
        }

        fn seed_parliament_permissionless_progress_fixture(
            state_transaction: &mut StateTransaction<'_, '_>,
            phase: ParliamentPermissionlessProgressPhase,
        ) -> ParliamentPermissionlessProgressFixture {
            const REQUEST_HEIGHT: u64 = 1;
            const PULSE_HEIGHT: u64 = 6;

            let proposal = parliament_permissionless_progress_proposal();
            let proposal_id = proposal.fingerprint();
            let proposal_content_id = ProposalContentId::new(proposal_id);
            let governance_attempt_id = GovernanceAttemptId::derive_v1(proposal_content_id, 0);
            let (risk_tier, requirements) = parliament_attempt_policy_v1(&proposal);
            let mut governance = parliament_test_governance(&requirements);
            governance.parliament_sortition_pulse_delay_blocks = PULSE_HEIGHT - REQUEST_HEIGHT;
            governance.parliament_invitation_phase_blocks = 1;
            state_transaction.gov = governance;
            let expected_head = parliament_expected_head_v1(&proposal, state_transaction)
                .expect("permissionless-progress proposal has a deterministic head");
            let mut attempt = crate::governance::parliament::ParliamentAttemptStateV1::try_new(
                GovernanceAttemptV1 {
                    id: governance_attempt_id,
                    proposal_content_id,
                    sequence: 0,
                    risk_tier,
                    stage: GovernanceStageV1::Qualification,
                    status: GovernanceAttemptStatusV1::Active,
                },
                PARLIAMENT_GOVERNANCE_POLICY_VERSION_V1,
                PULSE_HEIGHT - REQUEST_HEIGHT,
                // `PULSE_HEIGHT` is the first native pulse height.
                PULSE_HEIGHT + 1,
                proposal.effect_preimage_hash_v1(),
                expected_head,
                requirements.clone(),
            )
            .expect("create permissionless-progress Parliament attempt");
            attempt
                .complete_qualification(governance_attempt_id)
                .expect("complete permissionless-progress qualification");

            let candidates = parliament_test_candidates();
            let candidate_count =
                u32::try_from(candidates.len()).expect("fixture candidate count fits u32");
            let beacon_session_id = BeaconSessionId::for_network_v1(&state_transaction.network_id);
            let mut request_ids = Vec::with_capacity(requirements.len());
            for requirement in &requirements {
                let election_attempt_id =
                    BodyElectionAttemptId::derive_v1(governance_attempt_id, requirement.body, 0);
                let request = SortitionRequestV1::try_new_canonical(
                    governance_attempt_id,
                    election_attempt_id,
                    requirement.body,
                    parliament_candidate_root_v1(
                        governance_attempt_id,
                        requirement.body,
                        &candidates,
                    ),
                    candidate_count,
                    3,
                    REQUEST_HEIGHT,
                    PULSE_HEIGHT,
                    beacon_session_id,
                    None,
                )
                .expect("construct permissionless-progress sortition request");
                request_ids.push(request.id);
                attempt
                    .register_sortition_request(
                        governance_attempt_id,
                        0,
                        request,
                        candidates.clone(),
                    )
                    .expect("register permissionless-progress sortition request");
            }
            request_ids.sort_unstable();

            let pulse_id = if phase == ParliamentPermissionlessProgressPhase::AwaitingPulse {
                let (key_record, pulse) = crate::beacon::signed_persisted_pulse_fixture_for_world(
                    state_transaction.network_id,
                    PULSE_HEIGHT,
                    &state_transaction.execution_budget(),
                );
                state_transaction
                    .world
                    .global_beacon_key_sessions
                    .insert(key_record.session.session_id, key_record);
                state_transaction
                    .world
                    .global_beacon_pulses
                    .insert(pulse.pulse_id, pulse);
                state_transaction.world.global_beacon_pulse_slots.insert(
                    (
                        BeaconSessionId::for_network_v1(&pulse.network_id),
                        pulse.height,
                    ),
                    pulse.pulse_id,
                );
                BeaconPulseId::new(pulse.pulse_id)
            } else {
                let pulse_id = BeaconPulseId::new(parliament_test_root(0xB1));
                attempt
                    .consume_sortition_pulse_batch(
                        governance_attempt_id,
                        request_ids.clone(),
                        beacon_session_id,
                        PULSE_HEIGHT,
                        pulse_id,
                        parliament_test_root(0xB2),
                        &state_transaction.network_id,
                        &state_transaction.gov,
                    )
                    .expect("consume permissionless-progress sortition pulse");
                pulse_id
            };

            let election_attempt_id = BodyElectionAttemptId::derive_v1(
                governance_attempt_id,
                ParliamentBody::RulesCommittee,
                0,
            );
            if matches!(
                phase,
                ParliamentPermissionlessProgressPhase::InvitationsOpen
                    | ParliamentPermissionlessProgressPhase::InvitationsAccepted
            ) {
                attempt
                    .begin_invitation_acceptance(
                        governance_attempt_id,
                        election_attempt_id,
                        PULSE_HEIGHT,
                        state_transaction.gov.parliament_invitation_phase_blocks,
                    )
                    .expect("open permissionless-progress invitation window");
            }
            if phase == ParliamentPermissionlessProgressPhase::InvitationsAccepted {
                let members = attempt
                    .election(&election_attempt_id)
                    .expect("drawn permissionless-progress election")
                    .primary_assignments()
                    .iter()
                    .map(|assignment| assignment.member.clone())
                    .collect::<Vec<_>>();
                for member in members {
                    attempt
                        .record_invitation_response(
                            governance_attempt_id,
                            election_attempt_id,
                            &member,
                            true,
                            PULSE_HEIGHT,
                        )
                        .expect("accept permissionless-progress invitation");
                }
            }

            state_transaction
                .world
                .put_governance_proposal(
                    proposal_id,
                    crate::state::GovernanceProposalRecord {
                        proposer: ALICE_ID.clone(),
                        kind: proposal,
                        created_height: REQUEST_HEIGHT,
                        status: crate::state::GovernanceProposalStatus::Proposed,
                    },
                )
                .expect("store permissionless-progress proposal");
            state_transaction
                .world
                .put_parliament_attempt(attempt)
                .expect("store permissionless-progress Parliament attempt");
            let manager_permission: Permission = CanManageParliament.into();
            assert!(
                !has_exact_permission(&state_transaction.world, &ALICE_ID, &manager_permission,),
                "permissionless-progress relayer fixture must not grant manager authority"
            );

            ParliamentPermissionlessProgressFixture {
                governance_attempt_id,
                election_attempt_id,
                request_ids,
                beacon_session_id,
                pulse_height: PULSE_HEIGHT,
                pulse_id,
            }
        }

        struct ParliamentPermissionlessCorpusFixture {
            governance_attempt_id: GovernanceAttemptId,
            ballot_attempt_id: BallotAttemptId,
            ballot_records: Vec<Vec<u8>>,
        }

        fn seed_parliament_permissionless_corpus_fixture(
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> ParliamentPermissionlessCorpusFixture {
            use iroha_data_model::governance::types::DeliberationPhaseV1;

            let progress = seed_parliament_permissionless_progress_fixture(
                state_transaction,
                ParliamentPermissionlessProgressPhase::Drawing,
            );
            let governance_attempt_id = progress.governance_attempt_id;
            let mut attempt = state_transaction
                .world
                .parliament_attempts
                .get(&governance_attempt_id)
                .cloned()
                .expect("permissionless corpus fixture attempt");
            let requirements = attempt.required_bodies().to_vec();
            let (policy_requirement, public_requirements) = requirements
                .split_last()
                .expect("canonical Parliament pipeline is nonempty");
            assert_eq!(policy_requirement.body, ParliamentBody::PolicyJury);
            assert_eq!(
                policy_requirement.decision_mode,
                ParliamentDecisionModeV1::HiddenBindingBallot
            );
            for (index, requirement) in public_requirements.iter().copied().enumerate() {
                let election_attempt_id =
                    BodyElectionAttemptId::derive_v1(governance_attempt_id, requirement.body, 0);
                complete_parliament_body_for_due_certificate(
                    &mut attempt,
                    requirement,
                    election_attempt_id,
                    0x40_u8.wrapping_add(u8::try_from(index).expect("small body index")),
                );
            }

            let policy_election_id =
                BodyElectionAttemptId::derive_v1(governance_attempt_id, policy_requirement.body, 0);
            attempt
                .begin_invitation_acceptance(governance_attempt_id, policy_election_id, 20, 1)
                .expect("open Policy Jury invitation window");
            let policy_members = attempt
                .election(&policy_election_id)
                .expect("drawn Policy Jury election")
                .primary_assignments()
                .iter()
                .map(|assignment| assignment.member.clone())
                .collect::<Vec<_>>();
            for member in &policy_members {
                attempt
                    .record_invitation_response(
                        governance_attempt_id,
                        policy_election_id,
                        member,
                        true,
                        20,
                    )
                    .expect("accept Policy Jury invitation");
            }
            let body_instance_id = attempt
                .seal_body_roster(governance_attempt_id, policy_election_id, 21)
                .expect("seal Policy Jury roster");
            for phase in [
                DeliberationPhaseV1::Orientation,
                DeliberationPhaseV1::Evidence,
                DeliberationPhaseV1::Questions,
                DeliberationPhaseV1::Responses,
                DeliberationPhaseV1::Deliberation,
                DeliberationPhaseV1::Reflection,
                DeliberationPhaseV1::Vote,
            ] {
                attempt
                    .advance_body_phase(governance_attempt_id, body_instance_id, phase, 22, 10)
                    .expect("advance Policy Jury to its private ballot");
            }

            let ordered_tle_roster = (0_u8..4)
                .map(|index| {
                    let keypair = KeyPair::from_seed(
                        vec![0xD8_u8.wrapping_add(index); 32],
                        Algorithm::Ed25519,
                    );
                    iroha_model_base::peer::PeerId::new(keypair.public_key().clone())
                })
                .collect::<Vec<_>>();
            let threshold_session = ThresholdBlsSession::<TleReleasePurpose>::new(
                *state_transaction.network_id.as_bytes(),
                parliament_test_root(0xD1),
                crate::beacon::global_threshold_beacon_roster_hash_v1(&ordered_tle_roster),
                4,
                2,
            )
            .expect("permissionless corpus threshold session");
            let parameters = AdaptiveThresholdBlsParameters::derive(&threshold_session)
                .expect("permissionless corpus threshold parameters");
            let mut rng = StdRng::from_seed([0xDB; 32]);
            let dealers = (1_u16..=3)
                .map(|index| {
                    DasRenDealerSecret::generate_with_rng(&parameters, index, &mut rng)
                        .expect("permissionless corpus TLE dealer")
                        .1
                })
                .collect::<Vec<_>>();
            let tle_key = crate::tle_release::ValidatedTleKeySessionV1::from_qualified_dealers(
                threshold_session,
                &dealers,
                &[1, 2, 3],
                parliament_test_root(0xDC),
            )
            .expect("permissionless corpus TLE key");
            let tle_key_session_id = tle_key.public_state().key_session_id;
            state_transaction
                .world
                .put_tle_key_session(tle_key.public_state().clone(), ordered_tle_roster)
                .expect("persist permissionless corpus TLE key");

            let ballot_attempt_id = BallotAttemptId::derive_v1(body_instance_id, 0);
            let release_beacon_session_id = BeaconSessionId::new(parliament_test_root(0xD0));
            let release_height = 42;
            let tle_session_id = TleSessionId::derive_v1(
                ballot_attempt_id,
                tle_key_session_id,
                release_beacon_session_id,
                release_height,
            );
            attempt
                .register_ballot_attempt(
                    governance_attempt_id,
                    body_instance_id,
                    ballot_attempt_id,
                    0,
                    tle_session_id,
                    tle_key_session_id,
                    release_beacon_session_id,
                    30,
                    ParliamentTimedOvn {
                        registration_phase_blocks: 4,
                        survivor_freeze_phase_blocks: 3,
                        commitment_phase_blocks: 1,
                        release_delay_blocks: 4,
                        opening_phase_blocks: 2,
                        max_ballot_retries: 2,
                        max_corpus_entries: 3,
                    },
                    release_height,
                )
                .expect("register permissionless corpus ballot");
            let session = TimedOvnSessionPublicV1 {
                network_id: *state_transaction.network_id.as_bytes(),
                proposal_content_id: *attempt.proposal_content_id().as_bytes(),
                governance_attempt_id: *governance_attempt_id.as_bytes(),
                body_instance_id: *body_instance_id.as_bytes(),
                ballot_attempt_id: *ballot_attempt_id.as_bytes(),
                parameter_hash: timed_ovn_parameter_hash_v1(),
                tle_key_session_id,
                tle_key_transcript_hash: tle_key.public_state().transcript_hash,
                tle_master_public_key: *tle_key.master_public_key().as_bytes(),
            };
            let crypto_session = session
                .rebuild(&tle_key)
                .expect("rebuild permissionless corpus timed-OVN session");
            let mut registrations = policy_members
                .iter()
                .map(|member| {
                    let participant_hash =
                        parliament_ballot_participant_hash_v1(ballot_attempt_id, member);
                    let (secret, registration) = TimedOvnRegistrationSecretV1::generate_with_rng(
                        &crypto_session,
                        participant_hash,
                        &mut rng,
                    )
                    .expect("generate permissionless corpus registration");
                    (participant_hash, secret, registration.to_bytes())
                })
                .collect::<Vec<_>>();
            registrations.sort_unstable_by_key(|(participant_hash, _, _)| *participant_hash);
            let mut lifecycle =
                TimedOvnLifecycleStateV1::open_registration(session, 30, release_height, &tle_key)
                    .expect("open permissionless corpus registration");
            for (participant_hash, _, registration) in &registrations {
                lifecycle = lifecycle
                    .register_participant(*participant_hash, registration.clone(), &tle_key)
                    .expect("register permissionless corpus participant");
            }
            lifecycle = lifecycle
                .close_registration(&tle_key)
                .expect("close permissionless corpus registration");
            let (registration_binding, _) = lifecycle
                .validated_parliament_reducer_binding(&tle_key)
                .expect("derive permissionless corpus registration binding");
            attempt
                .close_ballot_registration(
                    governance_attempt_id,
                    ballot_attempt_id,
                    registration_binding
                        .registration_root
                        .expect("registration root"),
                    registration_binding
                        .registered_voters
                        .expect("registered voter count"),
                    34,
                )
                .expect("close permissionless corpus reducer registration");
            lifecycle = lifecycle
                .freeze_survivors(&tle_key)
                .expect("freeze permissionless corpus survivors");
            let (survivor_binding, _) = lifecycle
                .validated_parliament_reducer_binding(&tle_key)
                .expect("derive permissionless corpus survivor binding");
            attempt
                .freeze_ballot_survivors(
                    governance_attempt_id,
                    ballot_attempt_id,
                    survivor_binding.dropout_root.expect("dropout root"),
                    survivor_binding.survivor_root.expect("survivor root"),
                    survivor_binding.survivors.expect("survivor count"),
                    survivor_binding.no_recovery_root.expect("no-recovery root"),
                    37,
                )
                .expect("freeze permissionless corpus reducer survivors");
            let TimedOvnLifecycleStateV1::SurvivorsFrozen(frozen) = &lifecycle else {
                unreachable!("survivor freeze returns the frozen phase")
            };
            let prepared = frozen
                .validate(&tle_key)
                .expect("validate permissionless corpus survivor roster");
            let choices = [
                TimedOvnChoiceV1::Aye,
                TimedOvnChoiceV1::Nay,
                TimedOvnChoiceV1::Abstain,
            ];
            let ballot_records = registrations
                .iter()
                .zip(choices)
                .map(|((_, secret, _), choice)| {
                    secret
                        .cast_ballot_with_rng(prepared.survivor_roster(), choice, &mut rng)
                        .expect("cast permissionless corpus ballot")
                        .to_bytes()
                })
                .collect::<Vec<_>>();
            assert_eq!(ballot_records.len(), policy_members.len());

            state_transaction
                .world
                .put_parliament_attempt(attempt)
                .expect("persist permissionless corpus attempt");
            state_transaction
                .world
                .timed_ovn_evidence
                .insert(ballot_attempt_id, lifecycle);
            let manager_permission: Permission = CanManageParliament.into();
            assert!(
                !has_exact_permission(&state_transaction.world, &ALICE_ID, &manager_permission,),
                "permissionless corpus fixture must not grant manager authority"
            );

            ParliamentPermissionlessCorpusFixture {
                governance_attempt_id,
                ballot_attempt_id,
                ballot_records,
            }
        }

        #[test]
        fn parliament_sortition_pulse_consumption_is_permissionless_and_exactly_bound() {
            use iroha_data_model::governance::types::BodyElectionAttemptStatusV1;

            let state = blank_test_state();
            let block = new_dummy_block_at_height(NonZeroU64::new(6).expect("nonzero height"));
            let mut state_block = state.block(block.as_ref().header());
            let mut state_transaction = state_block.transaction();
            let fixture = seed_parliament_permissionless_progress_fixture(
                &mut state_transaction,
                ParliamentPermissionlessProgressPhase::AwaitingPulse,
            );

            let mut incomplete_request_ids = fixture.request_ids.clone();
            incomplete_request_ids.pop();
            let error = gov::SubmitParliamentLifecycleTransitionV1 {
                governance_attempt_id: fixture.governance_attempt_id,
                transition: gov::ParliamentLifecycleTransitionV1::ConsumeSortitionPulseBatch(
                    gov::ParliamentConsumeSortitionPulseBatchV1 {
                        request_ids: incomplete_request_ids,
                        beacon_session_id: fixture.beacon_session_id,
                        pulse_height: fixture.pulse_height,
                        pulse_id: fixture.pulse_id,
                    },
                ),
            }
            .execute(&ALICE_ID, &mut state_transaction)
            .expect_err("a relayer cannot select an incomplete initial request batch");
            let rendered = format!("{error:?}");
            assert!(
                rendered.contains("future beacon pulse binding mismatch"),
                "unexpected incomplete pulse-batch rejection: {rendered}"
            );
            assert!(
                !rendered.contains("CanManageParliament"),
                "pulse binding must be reducer-owned rather than manager-gated: {rendered}"
            );
            assert_eq!(
                state_transaction
                    .world
                    .parliament_attempts
                    .get(&fixture.governance_attempt_id)
                    .expect("retained permissionless-progress attempt")
                    .election(&fixture.election_attempt_id)
                    .expect("retained permissionless-progress election")
                    .attempt()
                    .status,
                BodyElectionAttemptStatusV1::AwaitingPulse,
                "a rejected relayer-selected request subset must not mutate the draw"
            );

            // The wait is exact. The block is past the frozen slot and the pulse is committed,
            // yet nothing but the pulse of that slot moves the election: it cannot be failed,
            // and no other height or pulse identifier substitutes the draw.
            let awaiting_pulse = |state_transaction: &StateTransaction<'_, '_>| {
                state_transaction
                    .world
                    .parliament_attempts
                    .get(&fixture.governance_attempt_id)
                    .expect("retained permissionless-progress attempt")
                    .election(&fixture.election_attempt_id)
                    .expect("retained permissionless-progress election")
                    .attempt()
                    .status
                    == BodyElectionAttemptStatusV1::AwaitingPulse
            };
            let error = gov::SubmitParliamentLifecycleTransitionV1 {
                governance_attempt_id: fixture.governance_attempt_id,
                transition: gov::ParliamentLifecycleTransitionV1::FailBodyElectionNoRoster(
                    gov::ParliamentFailBodyElectionNoRosterV1 {
                        election_attempt_id: fixture.election_attempt_id,
                    },
                ),
            }
            .execute(&ALICE_ID, &mut state_transaction)
            .expect_err("an election awaiting its pulse can never be failed");
            let rendered = format!("{error:?}");
            assert!(
                rendered.contains("invalid or replayed BodyElection lifecycle transition"),
                "unexpected pulse-wait failure rejection: {rendered}"
            );
            assert!(awaiting_pulse(&state_transaction));
            for (pulse_height, pulse_id, expected) in [
                (
                    fixture.pulse_height + 1,
                    fixture.pulse_id,
                    "does not match the persisted finalized beacon pulse",
                ),
                (
                    fixture.pulse_height,
                    iroha_data_model::governance::types::BeaconPulseId::new([0xE3; 32]),
                    "unknown finalized beacon pulse",
                ),
            ] {
                let error = gov::SubmitParliamentLifecycleTransitionV1 {
                    governance_attempt_id: fixture.governance_attempt_id,
                    transition: gov::ParliamentLifecycleTransitionV1::ConsumeSortitionPulseBatch(
                        gov::ParliamentConsumeSortitionPulseBatchV1 {
                            request_ids: fixture.request_ids.clone(),
                            beacon_session_id: fixture.beacon_session_id,
                            pulse_height,
                            pulse_id,
                        },
                    ),
                }
                .execute(&ALICE_ID, &mut state_transaction)
                .expect_err("a substituted pulse never draws");
                let rendered = format!("{error:?}");
                assert!(
                    rendered.contains(expected),
                    "unexpected substituted-pulse rejection: {rendered}"
                );
                assert!(awaiting_pulse(&state_transaction));
            }

            gov::SubmitParliamentLifecycleTransitionV1 {
                governance_attempt_id: fixture.governance_attempt_id,
                transition: gov::ParliamentLifecycleTransitionV1::ConsumeSortitionPulseBatch(
                    gov::ParliamentConsumeSortitionPulseBatchV1 {
                        request_ids: fixture.request_ids,
                        beacon_session_id: fixture.beacon_session_id,
                        pulse_height: fixture.pulse_height,
                        pulse_id: fixture.pulse_id,
                    },
                ),
            }
            .execute(&ALICE_ID, &mut state_transaction)
            .expect("a non-manager may relay the exact finalized sortition pulse");
            let election = state_transaction
                .world
                .parliament_attempts
                .get(&fixture.governance_attempt_id)
                .expect("updated permissionless-progress attempt")
                .election(&fixture.election_attempt_id)
                .expect("updated permissionless-progress election");
            assert_eq!(
                election.attempt().status,
                BodyElectionAttemptStatusV1::Drawing
            );
            assert_eq!(election.pulse_id(), Some(fixture.pulse_id));
            assert!(election.pulse_output().is_some());
            assert!(
                !election.primary_assignments().is_empty(),
                "Core must derive the roster candidates from the verified pulse"
            );
        }

