        #[test]
        fn parliament_roster_sealing_is_permissionless_and_transcript_derived() {
            use iroha_data_model::governance::types::{
                BodyElectionAttemptStatusV1, parliament_roster_root_v1,
            };

            let state = blank_test_state();
            let block = new_dummy_block_at_height(NonZeroU64::new(7).expect("nonzero height"));
            let mut state_block = state.block(block.as_ref().header());
            let mut state_transaction = state_block.transaction();
            let fixture = seed_parliament_permissionless_progress_fixture(
                &mut state_transaction,
                ParliamentPermissionlessProgressPhase::InvitationsAccepted,
            );
            let mut assignments = state_transaction
                .world
                .parliament_attempts
                .get(&fixture.governance_attempt_id)
                .expect("retained permissionless-progress attempt")
                .election(&fixture.election_attempt_id)
                .expect("retained permissionless-progress election")
                .primary_assignments()
                .to_vec();
            assignments.sort_unstable_by_key(|assignment| assignment.assignment_id);
            let expected_roster_root =
                parliament_roster_root_v1(fixture.election_attempt_id, &assignments);
            let expected_body_id = iroha_data_model::governance::types::BodyInstanceId::derive_v1(
                fixture.election_attempt_id,
                expected_roster_root,
            );

            let error = gov::SubmitParliamentLifecycleTransitionV1 {
                governance_attempt_id: fixture.governance_attempt_id,
                transition: gov::ParliamentLifecycleTransitionV1::SealBodyRoster(
                    gov::ParliamentSealBodyRosterV1 {
                        election_attempt_id: BodyElectionAttemptId::new([0xE3; 32]),
                    },
                ),
            }
            .execute(&ALICE_ID, &mut state_transaction)
            .expect_err("a relayer cannot choose an unknown election roster");
            let rendered = format!("{error:?}");
            assert!(rendered.contains("unknown BodyElection"));
            assert!(!rendered.contains("CanManageParliament"));
            assert_eq!(
                state_transaction
                    .world
                    .parliament_attempts
                    .get(&fixture.governance_attempt_id)
                    .expect("retained permissionless-progress attempt")
                    .election(&fixture.election_attempt_id)
                    .expect("retained permissionless-progress election")
                    .attempt()
                    .status,
                BodyElectionAttemptStatusV1::AcceptingInvitations
            );

            gov::SubmitParliamentLifecycleTransitionV1 {
                governance_attempt_id: fixture.governance_attempt_id,
                transition: gov::ParliamentLifecycleTransitionV1::SealBodyRoster(
                    gov::ParliamentSealBodyRosterV1 {
                        election_attempt_id: fixture.election_attempt_id,
                    },
                ),
            }
            .execute(&ALICE_ID, &mut state_transaction)
            .expect("a non-manager may seal the exact accepted invitation transcript");
            let attempt = state_transaction
                .world
                .parliament_attempts
                .get(&fixture.governance_attempt_id)
                .expect("updated permissionless-progress attempt");
            assert_eq!(
                attempt
                    .election(&fixture.election_attempt_id)
                    .expect("sealed permissionless-progress election")
                    .attempt()
                    .status,
                BodyElectionAttemptStatusV1::Sealed
            );
            assert_eq!(
                attempt
                    .sealed_body_for_role(ParliamentBody::RulesCommittee)
                    .expect("Core-derived Rules Committee roster")
                    .instance()
                    .id,
                expected_body_id,
                "the relayer cannot choose the roster root or body-instance identifier"
            );
        }

        fn complete_parliament_body_for_due_certificate(
            attempt: &mut crate::governance::parliament::ParliamentAttemptStateV1,
            requirement: RequiredParliamentBodyV1,
            election_attempt_id: BodyElectionAttemptId,
            result_tag: u8,
        ) -> u64 {
            let governance_attempt_id = attempt.attempt().id;
            attempt
                .begin_invitation_acceptance(governance_attempt_id, election_attempt_id, 20, 1)
                .expect("open deterministic Parliament invitation window");
            let members = attempt
                .election(&election_attempt_id)
                .expect("drawn Parliament election")
                .primary_assignments()
                .iter()
                .map(|assignment| assignment.member.clone())
                .collect::<Vec<_>>();
            for member in &members {
                attempt
                    .record_invitation_response(
                        governance_attempt_id,
                        election_attempt_id,
                        member,
                        true,
                        20,
                    )
                    .expect("accept deterministic Parliament invitation");
            }
            let body_instance_id = attempt
                .seal_body_roster(governance_attempt_id, election_attempt_id, 21)
                .expect("seal deterministic Parliament roster");
            let mut phases = vec![
                iroha_data_model::governance::types::DeliberationPhaseV1::Orientation,
                iroha_data_model::governance::types::DeliberationPhaseV1::Evidence,
                iroha_data_model::governance::types::DeliberationPhaseV1::Questions,
                iroha_data_model::governance::types::DeliberationPhaseV1::Responses,
                iroha_data_model::governance::types::DeliberationPhaseV1::Deliberation,
                iroha_data_model::governance::types::DeliberationPhaseV1::Reflection,
            ];
            if requirement.decision_mode == ParliamentDecisionModeV1::HiddenBindingBallot {
                phases.push(iroha_data_model::governance::types::DeliberationPhaseV1::Vote);
            }
            for phase in phases {
                attempt
                    .advance_body_phase(governance_attempt_id, body_instance_id, phase, 22, 10)
                    .expect("advance deterministic Parliament deliberation");
            }

            match requirement.decision_mode {
                ParliamentDecisionModeV1::PublicFinding => {
                    let result_root = parliament_test_root(result_tag);
                    let mut finalized = false;
                    for member in &members {
                        finalized = attempt
                            .endorse_public_finding(
                                governance_attempt_id,
                                body_instance_id,
                                result_root,
                                member,
                                22,
                            )
                            .expect("endorse deterministic public finding");
                        if finalized {
                            break;
                        }
                    }
                    assert!(
                        finalized,
                        "three seats must reach the two-thirds finding quorum"
                    );
                }
                ParliamentDecisionModeV1::HiddenBindingBallot => {
                    let ballot_attempt_id = BallotAttemptId::derive_v1(body_instance_id, 0);
                    let release_beacon_session_id =
                        BeaconSessionId::new(parliament_test_root(0xD0));
                    let tle_key_session_id = TleKeySessionId::new(parliament_test_root(0xD1));
                    let release_height = 42;
                    let tle_session_id = TleSessionId::derive_v1(
                        ballot_attempt_id,
                        tle_key_session_id,
                        release_beacon_session_id,
                        release_height,
                    );
                    attempt
                        .register_ballot_attempt(
                            governance_attempt_id,
                            body_instance_id,
                            ballot_attempt_id,
                            0,
                            tle_session_id,
                            tle_key_session_id,
                            release_beacon_session_id,
                            30,
                            ParliamentTimedOvn {
                                registration_phase_blocks: 4,
                                survivor_freeze_phase_blocks: 3,
                                commitment_phase_blocks: 1,
                                release_delay_blocks: 4,
                                opening_phase_blocks: 2,
                                max_ballot_retries: 2,
                                max_corpus_entries: 3,
                            },
                            release_height,
                        )
                        .expect("register deterministic binding ballot");
                    let registration_root = parliament_test_root(0xD2);
                    let dropout_root = parliament_test_root(0xD3);
                    let survivor_root = parliament_test_root(0xD4);
                    let no_recovery_root = parliament_test_root(0xD5);
                    let corpus_root = parliament_test_root(0xD6);
                    let timed_commitment_root = parliament_test_root(0xD7);
                    attempt
                        .close_ballot_registration(
                            governance_attempt_id,
                            ballot_attempt_id,
                            registration_root,
                            3,
                            34,
                        )
                        .expect("close deterministic ballot registration");
                    attempt
                        .freeze_ballot_survivors(
                            governance_attempt_id,
                            ballot_attempt_id,
                            dropout_root,
                            survivor_root,
                            3,
                            no_recovery_root,
                            37,
                        )
                        .expect("freeze deterministic ballot survivors");
                    attempt
                        .freeze_timed_ovn_corpus(
                            governance_attempt_id,
                            ballot_attempt_id,
                            corpus_root,
                            survivor_root,
                            3,
                            timed_commitment_root,
                            38,
                        )
                        .expect("freeze deterministic timed-OVN corpus");
                    attempt
                        .begin_ballot_opening_batch(
                            governance_attempt_id,
                            vec![ballot_attempt_id],
                            release_beacon_session_id,
                            release_height,
                            release_height,
                            BeaconPulseId::new(parliament_test_root(0xD8)),
                        )
                        .expect("open deterministic timed ballot");
                    let outcome = attempt
                        .finalize_opened_ballot(
                            governance_attempt_id,
                            ballot_attempt_id,
                            corpus_root,
                            no_recovery_root,
                            tle_session_id,
                            parliament_test_root(0xD9),
                            3,
                            ParliamentAggregateTallyV1 {
                                original_seats: 3,
                                accepted_ballots: 3,
                                aye: 2,
                                nay: 1,
                                abstain: 0,
                            },
                            2,
                            43,
                        )
                        .expect("finalize deterministic aggregate ballot");
                    assert_eq!(outcome, ParliamentAggregateOutcomeV1::Approved);
                }
            }
            attempt
                .body(&body_instance_id)
                .and_then(|body| body.result_height())
                .expect("completed due-certificate body result height")
        }

        /// Seed only the fixture's pristine World with the existing reducer-produced due
        /// certificate. This is not a native block, a CommitQC or live ballot qualification.
        /// The later genuine native H60 block alone executes the scheduled effect.
        pub(crate) fn seed_sccp_native_proof_certificate_before_genesis(
            state: &State,
            proposal: &iroha_data_model::sccp::governance::SccpGovernanceProposalV1,
        ) -> GovernanceCertificateV1 {
            assert_eq!(
                state.view().height(),
                0,
                "fixture seeding precedes native genesis"
            );
            assert_eq!(*state.view().network_id(), proposal.network_id);
            let header = iroha_data_model::block::BlockHeader::new(
                NonZeroU64::new(PARLIAMENT_DUE_CERTIFICATE_HEIGHT).unwrap(),
                None,
                None,
                PARLIAMENT_DUE_CERTIFICATE_HEIGHT * 1_000,
                0,
            );
            let mut block = state.block(header);
            let fixture = {
                let mut transaction = block.transaction();
                let fixture = seed_due_parliament_certificate(
                    &mut transaction,
                    sccp_route_governance_test_kind(proposal),
                );
                transaction.apply();
                fixture
            };
            block
                .commit_world_overlay_for_testing()
                .expect("publish pristine fixture preconditions");
            assert_eq!(state.view().height(), 0);
            fixture.certificate
        }

        fn seed_due_parliament_certificate(
            state_transaction: &mut StateTransaction<'_, '_>,
            proposal_kind: ProposalKind,
        ) -> DueParliamentCertificateFixture {
            assert_eq!(
                state_transaction.block_height(),
                PARLIAMENT_DUE_CERTIFICATE_HEIGHT
            );
            let proposal_id = proposal_kind.fingerprint();
            let proposal_content_id = ProposalContentId::new(proposal_id);
            let governance_attempt_id = GovernanceAttemptId::derive_v1(proposal_content_id, 0);
            let (risk_tier, requirements) = parliament_attempt_policy_v1(&proposal_kind);
            let expected_head = parliament_expected_head_v1(&proposal_kind, state_transaction)
                .expect("derive deterministic governed head");
            let mut attempt = crate::governance::parliament::ParliamentAttemptStateV1::try_new(
                GovernanceAttemptV1 {
                    id: governance_attempt_id,
                    proposal_content_id,
                    sequence: 0,
                    risk_tier,
                    stage: GovernanceStageV1::Qualification,
                    status: GovernanceAttemptStatusV1::Active,
                },
                PARLIAMENT_GOVERNANCE_POLICY_VERSION_V1,
                10,
                // Height 20, the fixture's sortition slot, is the first native pulse height.
                21,
                proposal_kind.effect_preimage_hash_v1(),
                expected_head,
                requirements.clone(),
            )
            .expect("create proposal-bound Parliament attempt");
            attempt
                .complete_qualification(governance_attempt_id)
                .expect("complete deterministic qualification");

            let candidates = parliament_test_candidates();
            let candidate_count =
                u32::try_from(candidates.len()).expect("fixture candidate count fits u32");
            let sortition_session = BeaconSessionId::new(parliament_test_root(0xB0));
            let mut request_ids = Vec::with_capacity(requirements.len());
            for requirement in &requirements {
                let election_attempt_id =
                    BodyElectionAttemptId::derive_v1(governance_attempt_id, requirement.body, 0);
                let request = SortitionRequestV1::try_new_canonical(
                    governance_attempt_id,
                    election_attempt_id,
                    requirement.body,
                    parliament_candidate_root_v1(
                        governance_attempt_id,
                        requirement.body,
                        &candidates,
                    ),
                    candidate_count,
                    3,
                    10,
                    20,
                    sortition_session,
                    None,
                )
                .expect("construct deterministic sortition request");
                request_ids.push(request.id);
                attempt
                    .register_sortition_request(
                        governance_attempt_id,
                        0,
                        request,
                        candidates.clone(),
                    )
                    .expect("register deterministic sortition request");
            }
            request_ids.sort_unstable();
            let sortition_pulse_id = BeaconPulseId::new(parliament_test_root(0xB1));
            attempt
                .consume_sortition_pulse_batch(
                    governance_attempt_id,
                    request_ids,
                    sortition_session,
                    20,
                    sortition_pulse_id,
                    *sortition_pulse_id.as_bytes(),
                    &state_transaction.network_id,
                    &parliament_test_governance(&requirements),
                )
                .expect("consume deterministic simultaneous Parliament draw");

            let mut certified_at_height = 0;
            for (index, requirement) in requirements.iter().copied().enumerate() {
                let result_height = complete_parliament_body_for_due_certificate(
                    &mut attempt,
                    requirement,
                    BodyElectionAttemptId::derive_v1(governance_attempt_id, requirement.body, 0),
                    0xC0_u8
                        .checked_add(u8::try_from(index).expect("fixture body index fits u8"))
                        .expect("fixture result tag does not overflow"),
                );
                certified_at_height = certified_at_height.max(result_height);
            }
            assert_eq!(attempt.attempt().stage, GovernanceStageV1::Certification);
            let certificate = attempt
                .construct_certificate(
                    governance_attempt_id,
                    certified_at_height,
                    PARLIAMENT_DUE_CERTIFICATE_HEIGHT,
                )
                .expect("construct complete exact-due Parliament certificate");
            certificate
                .validate()
                .expect("complete world-test certificate must validate");
            attempt
                .validate_proposal_bindings_v1(&proposal_kind)
                .expect("world-test attempt must retain exact proposal bindings");

            state_transaction
                .world
                .put_governance_proposal(
                    proposal_id,
                    crate::state::GovernanceProposalRecord {
                        proposer: proposal_kind
                            .proposal_operator_v1()
                            .cloned()
                            .unwrap_or_else(|| ALICE_ID.clone()),
                        kind: proposal_kind,
                        created_height: 1,
                        status: crate::state::GovernanceProposalStatus::Proposed,
                    },
                )
                .expect("world-test proposal must satisfy first-release JSON bounds");
            state_transaction
                .world
                .put_parliament_attempt(attempt)
                .expect("persist complete world-test Parliament attempt");
            DueParliamentCertificateFixture {
                proposal_id,
                governance_attempt_id,
                certificate,
            }
        }

        fn automatic_parliament_execution_event(
            state_transaction: &StateTransaction<'_, '_>,
        ) -> GovernanceParliamentLifecycleTransitionApplied {
            state_transaction
                .world
                .internal_event_buf
                .iter()
                .filter_map(|event| match event.as_ref() {
                    DataEvent::Governance(
                        GovernanceEvent::ParliamentLifecycleTransitionApplied(payload),
                    ) if payload.automatic_outcome.is_some() => Some(payload.clone()),
                    _ => None,
                })
                .next_back()
                .expect("automatic Parliament execution event")
        }

        fn assert_automatic_parliament_execution_event(
            state_transaction: &StateTransaction<'_, '_>,
            fixture: &DueParliamentCertificateFixture,
            outcome: gov::ParliamentAutomaticExecutionOutcomeV1,
        ) {
            let event = automatic_parliament_execution_event(state_transaction);
            assert_eq!(
                event.proposal_content_id,
                fixture.certificate.proposal_content_id
            );
            assert_eq!(event.governance_attempt_id, fixture.governance_attempt_id);
            assert_eq!(event.transition_kind, outcome.kind());
            assert_eq!(event.no_result_kind, None);
            assert_eq!(event.automatic_outcome, Some(outcome));
            assert_eq!(event.transition_digest, outcome.digest_v1());
            assert_eq!(
                event.certificate_id,
                Some(GovernanceCertificateId::derive_v1(&fixture.certificate))
            );
            assert_eq!(event.at_height, PARLIAMENT_DUE_CERTIFICATE_HEIGHT);
        }

        #[test]
        fn parliament_due_certificate_records_exact_native_control_cause() {
            use crate::smartcontracts::isi::sccp::{store, test_support::sample_route};
            use iroha_data_model::sccp::{
                governance::{
                    SccpGovernanceActionV1, SccpGovernanceProposalV1, SccpGovernanceSubjectV1,
                    SccpSetDestinationPausedActionV1,
                },
                params::SccpParametersV1,
            };
            let state = blank_test_state();
            let block = new_dummy_block_at_height(
                NonZeroU64::new(PARLIAMENT_DUE_CERTIFICATE_HEIGHT).expect("due height"),
            );
            let mut state_block = state.block(block.as_ref().header());
            let network = iroha_data_model::bridge::SccpNetworkV1::TonMainnet;
            let fixture = {
                let mut seed = state_block.transaction();
                Register::account(Account::new(ALICE_ID.clone()))
                    .execute(&ALICE_ID, &mut seed)
                    .expect("proposer");
                store::parameters::set(&mut seed, Some(SccpParametersV1::taira_default()));
                store::routes::insert(&mut seed, network, sample_route(network)).expect("route");
                let proposal = SccpGovernanceProposalV1 {
                    network_id: *seed.network_id(),
                    base_revisions: vec![
                        (SccpGovernanceSubjectV1::RouteControl(network), 0).into(),
                    ],
                    actions: vec![SccpGovernanceActionV1::SetDestinationPaused(
                        SccpSetDestinationPausedActionV1 {
                            network,
                            revision: 1,
                            paused: true,
                        },
                    )],
                };
                let fixture = seed_due_parliament_certificate(
                    &mut seed,
                    ProposalKind::SccpRouteGovernance(SccpRouteGovernanceProposal {
                        proposal: Box::new(proposal),
                    }),
                );
                seed.apply();
                fixture
            };
            let mut malformed = fixture.certificate.clone();
            malformed.effect_preimage_hash = [0; 32];
            crate::smartcontracts::isi::sccp::controls::ControlCauseV1::from_parliament_certificate(
                &malformed,
            ).expect_err("zero effect is not a native authority");
            let mut execution = state_block.transaction();
            assert_eq!(
                execute_due_parliament_certificate_v1(
                    fixture.governance_attempt_id,
                    &mut execution
                )
                .expect("execute exact certificate"),
                DueParliamentCertificateExecutionV1::Applied
            );
            let record = store::control_messages::get(&*execution.world, &(network, 1, 1))
                .expect("native control");
            assert_eq!(record.track, 1);
            assert!(record.parliament_paused);
            assert_eq!(record.fast_pause_until_ms, 0);
            assert_eq!(
                record.certificate_id,
                *GovernanceCertificateId::derive_v1(&fixture.certificate).as_bytes()
            );
            assert_ne!(record.certificate_id, fixture.proposal_id);
            assert_eq!(record.effect_hash, fixture.certificate.effect_preimage_hash);
            assert_eq!(record.height, PARLIAMENT_DUE_CERTIFICATE_HEIGHT);
            assert_eq!(record.commitment_index, 0);
            let revision = &store::routes::get(&*execution.world, &network)
                .expect("route")
                .revisions[&1];
            assert_eq!(
                record.leaf,
                iroha_sccp::v1::control::control_leaf(
                    execution.network_id().as_bytes(),
                    network,
                    &revision.destination_word,
                    &iroha_sccp::v1::control::ControlLeafV1 {
                        route_revision: 1,
                        control_nonce: 1,
                        track: 1,
                        parliament_paused: 1,
                        fast_pause_until_ms: 0,
                        certificate_id: record.certificate_id,
                        effect_hash: record.effect_hash,
                    }
                )
                .expect("native control leaf")
            );
            assert_automatic_parliament_execution_event(
                &execution,
                &fixture,
                gov::ParliamentAutomaticExecutionOutcomeV1::Enacted,
            );
        }

        #[test]
        fn parliament_due_certificate_grants_and_revokes_exact_global_trigger_permission() {
            fn run(action: GlobalDataTriggerPermissionGovernanceActionV1, initially_granted: bool) {
                let state = blank_test_state();
                let block = new_dummy_block_at_height(
                    NonZeroU64::new(PARLIAMENT_DUE_CERTIFICATE_HEIGHT)
                        .expect("due height is nonzero"),
                );
                let mut state_block = state.block(block.as_ref().header());
                let permission = Permission::from(CanRegisterGlobalDataTrigger {
                    authority: ALICE_ID.clone(),
                });
                let fixture = {
                    let mut seed = state_block.transaction();
                    Register::account(Account::new(ALICE_ID.clone()))
                        .execute(&ALICE_ID, &mut seed)
                        .expect("seed exact permission target");
                    if initially_granted {
                        seed.world
                            .add_account_permission(&ALICE_ID, permission.clone());
                    }
                    let fixture = seed_due_parliament_certificate(
                        &mut seed,
                        ProposalKind::GlobalDataTriggerPermissionGovernance(
                            GlobalDataTriggerPermissionGovernanceProposalV1 {
                                authority: ALICE_ID.clone(),
                                action,
                            },
                        ),
                    );
                    seed.apply();
                    fixture
                };

                let mut execution = state_block.transaction();
                assert_eq!(
                    execute_due_parliament_certificate_v1(
                        fixture.governance_attempt_id,
                        &mut execution,
                    )
                    .expect("execute certified exact-account permission transition"),
                    DueParliamentCertificateExecutionV1::Applied
                );
                let is_granted = execution
                    .world
                    .account_permissions
                    .get(&ALICE_ID)
                    .is_some_and(|permissions| permissions.contains(&permission));
                assert_eq!(
                    is_granted,
                    action == GlobalDataTriggerPermissionGovernanceActionV1::Grant
                );
                let permission_event = execution.world.internal_event_buf.iter().any(|event| {
                    matches!(
                        event.as_ref(),
                        DataEvent::Account(AccountEvent::PermissionAdded(change))
                            | DataEvent::Account(AccountEvent::PermissionRemoved(change))
                            if change.account == *ALICE_ID && change.permission == permission
                    )
                });
                assert!(
                    permission_event,
                    "certified transition must emit an account event"
                );
            }

            run(GlobalDataTriggerPermissionGovernanceActionV1::Grant, false);
            run(GlobalDataTriggerPermissionGovernanceActionV1::Revoke, true);
        }

        #[test]
        fn parliament_due_certificate_completes_contract_ownership_transfer_to_account() {
            let state = blank_test_state();
            let block = new_dummy_block_at_height(
                NonZeroU64::new(PARLIAMENT_DUE_CERTIFICATE_HEIGHT).expect("due height is nonzero"),
            );
            let mut state_block = state.block(block.as_ref().header());
            let (fixture, contract_address) = {
                let mut seed = state_block.transaction();
                Register::account(Account::new(ALICE_ID.clone()))
                    .execute(&ALICE_ID, &mut seed)
                    .expect("seed proposer");
                Register::account(Account::new(BOB_ID.clone()))
                    .execute(&ALICE_ID, &mut seed)
                    .expect("seed proposed owner");
                let contract_address = ContractAddress::derive(
                    seed.network_id(),
                    &ALICE_ID,
                    81,
                    DataSpaceId::UNIVERSAL,
                )
                .expect("derive governed contract address");
                let contract_subject = contract_address.subject_id();
                Register::account(Account::new(contract_subject.clone()))
                    .execute(&ALICE_ID, &mut seed)
                    .expect("seed contract subject");
                seed.world.contract_subject_bindings.insert(
                    contract_address.clone(),
                    crate::smartcontracts::code::ContractSubjectBinding::new_parliament(
                        &contract_address,
                        ALICE_ID.clone(),
                        [0x81; 32],
                        [0x82; 32],
                    ),
                );
                seed.world
                    .contract_subject_addresses
                    .insert(contract_subject, contract_address.clone());
                let fixture = seed_due_parliament_certificate(
                    &mut seed,
                    ProposalKind::ContractLifecycleGovernance(
                        ContractLifecycleGovernanceProposalV1 {
                            proposal_operator: ALICE_ID.clone(),
                            contract_address: contract_address.clone(),
                            expected_revision: 1,
                            action: ContractLifecycleGovernanceActionV1::OfferOwnership(
                                iroha_data_model::governance::types::OfferContractOwnershipGovernanceActionV1 {
                                    new_owner: BOB_ID.clone(),
                                },
                            ),
                        },
                    ),
                );
                seed.apply();
                (fixture, contract_address)
            };

            let mut execution = state_block.transaction();
            assert_eq!(
                execute_due_parliament_certificate_v1(
                    fixture.governance_attempt_id,
                    &mut execution,
                )
                .expect("execute certified ownership offer"),
                DueParliamentCertificateExecutionV1::Applied
            );
            let lifecycle = &execution
                .world
                .contract_subject_bindings
                .get(&contract_address)
                .expect("governed lifecycle binding")
                .lifecycle;
            assert_eq!(lifecycle.revision, 2);
            assert_eq!(
                lifecycle.pending_owner,
                Some(
                    iroha_data_model::smart_contract::ContractLifecycleOwnerV1::Account(
                        BOB_ID.clone()
                    )
                )
            );
            assert_eq!(
                lifecycle.parliament_delegation,
                iroha_data_model::smart_contract::ContractParliamentDelegationV1::None
            );
            let offered_lifecycle = lifecycle.clone();
            assert_eq!(
                execution
                    .world
                    .governance_proposals
                    .get(&fixture.proposal_id)
                    .expect("governed proposal")
                    .status,
                crate::state::GovernanceProposalStatus::Enacted
            );
            let event = execution
                .world
                .internal_event_buf
                .iter()
                .find_map(|event| match event.as_ref() {
                    DataEvent::SmartContract(SmartContractEvent::OwnershipTransferOffered(
                        event,
                    )) if event.contract_address == contract_address => Some(event),
                    _ => None,
                })
                .expect("certified ownership event");
            assert_eq!(event.revision, 2);
            assert_eq!(event.lifecycle, offered_lifecycle);

            let stale = scode::AcceptContractOwnership {
                contract_address: contract_address.clone(),
                expected_revision: 1,
            }
            .execute(&BOB_ID, &mut execution)
            .expect_err("stale account acceptance must fail closed");
            assert!(
                matches!(
                    &stale,
                    InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(message)
                    ) if message.contains("stale contract lifecycle revision")
                ),
                "unexpected stale ownership-acceptance error: {stale:?}"
            );
            assert_eq!(
                execution
                    .world
                    .contract_subject_bindings
                    .get(&contract_address)
                    .expect("stale acceptance preserves lifecycle binding")
                    .lifecycle,
                offered_lifecycle
            );

            scode::AcceptContractOwnership {
                contract_address: contract_address.clone(),
                expected_revision: 2,
            }
            .execute(&BOB_ID, &mut execution)
            .expect("pending account completes Parliament ownership transfer");
            let lifecycle = &execution
                .world
                .contract_subject_bindings
                .get(&contract_address)
                .expect("transferred lifecycle binding")
                .lifecycle;
            assert_eq!(
                lifecycle.owner,
                iroha_data_model::smart_contract::ContractLifecycleOwnerV1::Account(BOB_ID.clone())
            );
            assert_eq!(lifecycle.revision, 3);
            assert!(lifecycle.pending_owner.is_none());
            assert_eq!(
                lifecycle.parliament_delegation,
                iroha_data_model::smart_contract::ContractParliamentDelegationV1::None
            );
            let stale_replay = scode::AcceptContractOwnership {
                contract_address,
                expected_revision: 2,
            }
            .execute(&BOB_ID, &mut execution)
            .expect_err("accepted ownership transfer cannot replay at the consumed revision");
            assert!(
                matches!(
                    &stale_replay,
                    InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(message)
                    ) if message.contains("stale contract lifecycle revision")
                ),
                "unexpected ownership-acceptance replay error: {stale_replay:?}"
            );
        }

