        fn certified_threshold_key_lifecycle_instruction_v1(
            state_transaction: &StateTransaction<'_, '_>,
            validator_keys: &[KeyPair],
            action: consensus_keys::ThresholdKeyLifecycleActionV1,
            session_id: [u8; 32],
            transcript_hash: [u8; 32],
            public_state: Vec<u8>,
        ) -> consensus_keys::ApplyThresholdKeyLifecycleCertificateV1 {
            let ordered_roster = state_transaction
                .threshold_key_lifecycle_frozen_roster_v1()
                .expect("lifecycle signing follows the exact scheduled committee");
            assert_eq!(ordered_roster.len(), validator_keys.len());
            for (peer, key) in ordered_roster.iter().zip(validator_keys) {
                assert_eq!(peer.public_key(), key.public_key());
            }
            let committee_size = u16::try_from(ordered_roster.len()).expect("small test roster");
            let quorum =
                u16::try_from((ordered_roster.len() - 1) / 3 * 2 + 1).expect("small test quorum");
            let expected_active_session_id = match action {
                consensus_keys::ThresholdKeyLifecycleActionV1::FinalizeGlobalBeaconKey => {
                    state_transaction
                        .world
                        .global_beacon_active_session()
                        .get(&crate::state::GLOBAL_THRESHOLD_BEACON_SINGLETON_KEY)
                        .copied()
                }
                consensus_keys::ThresholdKeyLifecycleActionV1::InstallParliamentTleKey
                | consensus_keys::ThresholdKeyLifecycleActionV1::RetireParliamentTleKey => {
                    state_transaction
                        .world
                        .active_tle_key_session()
                        .map(|session_id| *session_id.as_bytes())
                }
            };
            let mut certificate = consensus_keys::ThresholdKeyLifecycleCertificateV1 {
                version: crate::state::THRESHOLD_KEY_LIFECYCLE_CERTIFICATE_VERSION_V1,
                action,
                expected_active_session_id,
                effective_height: state_transaction.block_height(),
                network_id: state_transaction.network_id,
                roster_hash: crate::beacon::global_threshold_beacon_roster_hash_v1(&ordered_roster),
                committee_size,
                quorum,
                session_id,
                transcript_hash,
                public_state,
                signatures: Vec::new(),
            };
            let preimage =
                crate::state::threshold_key_lifecycle_certificate_preimage_v1(&certificate)
                    .expect("canonical lifecycle certificate preimage");
            certificate.signatures = validator_keys
                .iter()
                .take(usize::from(quorum))
                .enumerate()
                .map(
                    |(index, key)| consensus_keys::ThresholdKeyLifecycleSignatureV1 {
                        signer_index: u16::try_from(index).expect("small signer index"),
                        signature: Signature::try_new(key.private_key(), &preimage)
                            .expect("sign lifecycle certificate"),
                    },
                )
                .collect();
            consensus_keys::ApplyThresholdKeyLifecycleCertificateV1 { certificate }
        }

        world_test!(threshold_key_lifecycle_qc_rotates_tle_atomically_rejects_replay_and_blocks_retirement_at_inclusive_deadline {
            let state = blank_test_state();
            let header = BlockHeader::new(
                NonZeroU64::new(62).expect("nonzero lifecycle height"),
                None,
                None,
                0,
                0,
            );
            let mut state_block = state.block(header);
            let mut state_transaction = state_block.transaction();
            let validator_keys = (0..4).map(|_| checked_keypair()).collect::<Vec<_>>();
            let ordered_roster = validator_keys
                .iter()
                .map(|key| iroha_model_base::peer::PeerId::new(key.public_key().clone()))
                .collect::<Vec<_>>();
            *state_transaction.commit_topology.get_mut() = ordered_roster.clone();
            let roster_hash =
                crate::beacon::global_threshold_beacon_roster_hash_v1(&ordered_roster);

            let key_a = crate::tle_release::tests::public_key_session_fixture_for_context_v1(
                *state_transaction.network_id.as_bytes(),
                0xA2,
                roster_hash,
            );
            let key_a_id = key_a.key_session_id;
            state_transaction
                .world
                .put_tle_key_session(key_a.clone(), ordered_roster.clone())
                .expect("persist proof-valid predecessor TLE key A");
            let predecessor_install_height = state_transaction.block_height() - 1;
            let tle_lifecycle_policy = state_transaction.gov.parliament_tle_key_lifecycle;
            state_transaction
                .world
                .activate_tle_key_session(
                    key_a_id,
                    predecessor_install_height,
                    tle_lifecycle_policy,
                )
                .expect("predecessor TLE key A is active at the test height");
            assert_eq!(state_transaction.world.active_tle_key_session(), Some(key_a_id));
            assert_eq!(
                state_transaction
                    .world
                    .tle_key_session_rosters()
                    .get(&key_a_id),
                Some(&ordered_roster)
            );
            let key_b = crate::tle_release::tests::public_key_session_fixture_for_context_v1(
                *state_transaction.network_id.as_bytes(),
                0xB2,
                roster_hash,
            );
            let key_b_id = key_b.key_session_id;
            let key_c = crate::tle_release::tests::public_key_session_fixture_for_context_v1(
                *state_transaction.network_id.as_bytes(),
                0xC2,
                roster_hash,
            );
            let key_c_id = key_c.key_session_id;
            let stale_install_c = certified_threshold_key_lifecycle_instruction_v1(
                &state_transaction,
                &validator_keys,
                consensus_keys::ThresholdKeyLifecycleActionV1::InstallParliamentTleKey,
                *key_c_id.as_bytes(),
                key_c.transcript_hash,
                norito::encode_canonical(&key_c).expect("encode canonical TLE key C"),
            );
            let install_b = certified_threshold_key_lifecycle_instruction_v1(
                &state_transaction,
                &validator_keys,
                consensus_keys::ThresholdKeyLifecycleActionV1::InstallParliamentTleKey,
                *key_b_id.as_bytes(),
                key_b.transcript_hash,
                norito::encode_canonical(&key_b).expect("encode canonical TLE key B"),
            );
            install_b
                .clone()
                .execute(&ALICE_ID, &mut state_transaction)
                .expect("current-roster QC atomically rotates new ballots to TLE key B");
            assert_eq!(state_transaction.world.active_tle_key_session(), Some(key_b_id));
            assert!(state_transaction.world.tle_key_sessions.get(&key_a_id).is_some());
            assert_eq!(
                state_transaction
                    .world
                    .tle_key_session_rosters()
                    .get(&key_a_id),
                Some(&ordered_roster),
                "rotation retains the predecessor's exact seat binding"
            );
            assert_eq!(
                state_transaction
                    .world
                    .tle_key_session_rosters()
                    .get(&key_b_id),
                Some(&ordered_roster)
            );
            let replay = install_b
                .execute(&ALICE_ID, &mut state_transaction)
                .expect_err("an installed threshold-key certificate must not replay");
            assert!(format!("{replay:?}").contains("compare-and-set predecessor changed"));
            let stale_replacement = stale_install_c
                .execute(&ALICE_ID, &mut state_transaction)
                .expect_err("a certificate signed against predecessor A must not replace B");
            assert!(
                format!("{stale_replacement:?}")
                    .contains("compare-and-set predecessor changed")
            );
            assert_eq!(state_transaction.world.active_tle_key_session(), Some(key_b_id));
            assert!(state_transaction.world.tle_key_sessions.get(&key_c_id).is_none());

            let retaining_attempt =
                crate::governance::parliament::tests::tle_key_session_retention_attempt_fixture_v1(
                    key_b_id,
                );
            state_transaction
                .world
                .put_parliament_attempt(retaining_attempt)
                .expect("persist a proof-valid ballot retry retaining key B");
            let retire_b = certified_threshold_key_lifecycle_instruction_v1(
                &state_transaction,
                &validator_keys,
                consensus_keys::ThresholdKeyLifecycleActionV1::RetireParliamentTleKey,
                *key_b_id.as_bytes(),
                key_b.transcript_hash,
                Vec::new(),
            )
            .execute(&ALICE_ID, &mut state_transaction)
            .expect_err("the inclusive committed ballot deadline must block TLE retirement");
            assert!(format!("{retire_b:?}").contains("retained by a committed ballot deadline"));
            assert_eq!(state_transaction.world.active_tle_key_session(), Some(key_b_id));
        });

        world_test!(global_beacon_certificate_cannot_rotate_without_frozen_preparation {
            use crate::sumeragi::test_chain::CertifiedTestChain;
            use crate::state::StateReadOnly as _;
            // This maintained prefix includes the actual installed beacon authority
            // at H10; a mutable public-key pointer is not an incumbent certificate.
            let mut chain = CertifiedTestChain::npos_boundary_fixture();
            chain.commit(Vec::new());
            assert_eq!(chain.height(), 10);
            let state = chain.state();
            let parent = state.view().latest_block().expect("completed original State read").expect("original certified H10");
            let time_ms = u64::try_from(parent.header().creation_time().as_millis())
                .expect("original parent time fits")
                .checked_add(1).expect("successor clock follows its original parent");
            let header = BlockHeader::new(
                NonZeroU64::new(11).expect("nonzero lifecycle height"),
                state.view().latest_block_hash(),
                None,
                time_ms,
                0,
            );
            let mut block = state.block(header);
            let state_transaction = block.transaction();
            let (authority, authorization) =
                crate::state::validator_committee::current_authority(&state_transaction)
                    .expect("the incumbent owns authenticated native finality");
            let ordered_roster = state_transaction.threshold_key_lifecycle_frozen_roster_v1()
                .expect("the H11 roster is fixed by the committed consensus schedule");
            // Retain the maintained NPoS fixture's deterministic private custody and
            // prove every public seat against the actual source before signing.
            let mut validator_keys = [0xC1_u8, 0xC2, 0xC3, 0xC4].into_iter()
                .map(|seed| KeyPair::from_seed(vec![seed; 32], Algorithm::BlsNormal))
                .collect::<Vec<_>>();
            validator_keys.sort_by(|left, right| left.public_key().cmp(right.public_key()));
            assert_eq!(
                ordered_roster,
                validator_keys.iter().map(|key| PeerId::new(key.public_key().clone())).collect::<Vec<_>>()
            );
            let authorization_roster_hash =
                crate::beacon::global_threshold_beacon_roster_hash_v1(&ordered_roster);
            let mut successor_validator_keys =
                (0..4).map(|_| checked_keypair_with_algorithm(Algorithm::BlsNormal)).collect::<Vec<_>>();
            successor_validator_keys
                .sort_by(|left, right| left.public_key().cmp(right.public_key()));
            let successor_roster = successor_validator_keys
                .iter()
                .map(|key| iroha_model_base::peer::PeerId::new(key.public_key().clone()))
                .collect::<Vec<_>>();
            let successor_roster_hash =
                crate::beacon::global_threshold_beacon_roster_hash_v1(&successor_roster);
            assert_ne!(authorization_roster_hash, successor_roster_hash);

            let iroha_data_model::sumeragi::epoch::BeaconEpochBindingV1::Installed(incumbent) =
                authorization.beacon else {
                panic!("the committed boundary must retain its installed incumbent beacon");
            };
            let key_a = state_transaction.world.global_beacon_key_sessions
                .get(&incumbent.session_id).expect("retain the original incumbent DKG").clone();
            assert_eq!(key_a.session.transcript_hash, incumbent.transcript_hash);
            assert_eq!(key_a.session.network_id, authority.network_id);
            assert!(key_a.is_active_at(state_transaction.block_height()));
            assert!(state_transaction.world.validator_committee_transitions
                .get(&authorization.epoch.checked_add(1).expect("next epoch fits")).is_none());
            let (successor_session, _successor_signers) =
                crate::beacon::prepared_session_and_signers_fixture_for_keys_v1(
                    iroha_data_model::consensus::GlobalThresholdBeaconDkgSessionV1 {
                        version: iroha_data_model::consensus::GLOBAL_THRESHOLD_BEACON_VERSION_V1,
                        network_id: state_transaction.network_id,
                        session_id: [0xB4; 32],
                        attempt_id: [0xB4; 32],
                        authority_generation: authority.generation,
                        roster_hash: successor_roster_hash,
                        committee_size: 4,
                        threshold: 2,
                        start_height: 1,
                        commitments_end_height: 2,
                        deliveries_end_height: 3,
                        acceptances_end_height: 4,
                    },
                    &successor_validator_keys,
                    &state_transaction.execution_budget(),
                );
            let key_b = crate::beacon::FinalizedGlobalThresholdBeaconKeySessionRecordV1::new(
                successor_session.record().clone(), &state_transaction.execution_budget()
            ).expect("the successor retains a genuinely finalized DKG transcript");
            let install_b = certified_threshold_key_lifecycle_instruction_v1(
                &state_transaction,
                &validator_keys,
                consensus_keys::ThresholdKeyLifecycleActionV1::FinalizeGlobalBeaconKey,
                key_b.session.session_id,
                key_b.session.transcript_hash,
                norito::encode_canonical(&key_b).expect("encode canonical beacon key B"),
            );
            assert_eq!(
                install_b.certificate.roster_hash, authorization_roster_hash,
                "the block-H roster remains the sole lifecycle-signature authority"
            );
            assert_eq!(
                key_b.session.roster_hash, successor_roster_hash,
                "the signed public state independently names the H+1 DKG target"
            );
            state_transaction.apply();
            let mut state_transaction = block.transaction();
            let rejected = install_b
                .execute(&ALICE_ID, &mut state_transaction)
                .expect_err("a lifecycle QC cannot bypass authenticated committee preparation");
            assert!(
                matches!(rejected, InstructionExecutionError::InvariantViolation(ref message)
                    if message.as_ref() == "beacon finalization requires an authenticated frozen committee"),
                "the authenticated incumbent must reach its actual preparation refusal: {rejected:?}"
            );
            drop(state_transaction);
            let restored = block.transaction();
            // Neither the candidate record nor a retirement escapes transaction rollback.
            assert!(restored.world.global_beacon_key_sessions.get(&key_b.session.session_id).is_none());
            assert_eq!(restored.world.global_beacon_active_session.get(&crate::state::GLOBAL_THRESHOLD_BEACON_SINGLETON_KEY),Some(&key_a.session.session_id));
            assert_eq!(restored.world.global_beacon_key_sessions.get(&key_a.session.session_id),Some(&key_a));
        });

        world_test!(parliament_tle_rotation_cuts_over_at_next_height_and_retains_bound_openings {
            blank_state_transaction!(state, block, state_block, state_transaction);
            let validator_keys = (0..4).map(|_| checked_keypair()).collect::<Vec<_>>();
            let ordered_roster = validator_keys
                .iter()
                .map(|key| iroha_model_base::peer::PeerId::new(key.public_key().clone()))
                .collect::<Vec<_>>();
            *state_transaction.commit_topology.get_mut() = ordered_roster.clone();
            let roster_hash =
                crate::beacon::global_threshold_beacon_roster_hash_v1(&ordered_roster);
            let key_a = crate::tle_release::tests::public_key_session_fixture_for_context_v1(
                *state_transaction.network_id.as_bytes(),
                0xA1,
                roster_hash,
            );
            let key_b = crate::tle_release::tests::public_key_session_fixture_for_context_v1(
                *state_transaction.network_id.as_bytes(),
                0xB1,
                roster_hash,
            );
            let key_a_id = key_a.key_session_id;
            let key_b_id = key_b.key_session_id;
            let current_height = state_transaction.block_height();
            let predecessor_install_height = current_height
                .checked_sub(1)
                .expect("test block height leaves room for an active predecessor");
            let policy = state_transaction.gov.parliament_tle_key_lifecycle;

            state_transaction
                .world
                .put_tle_key_session(key_a, ordered_roster.clone())
                .expect("persist proof-valid TLE key A");
            state_transaction
                .world
                .activate_tle_key_session(key_a_id, predecessor_install_height, policy)
                .expect("activate TLE key A");
            super::validated_active_parliament_tle_key_session_for_new_ballot_v1(
                key_a_id,
                &state_transaction,
            )
            .expect("active key A must be selectable by a new ballot");

            state_transaction
                .world
                .put_tle_key_session(key_b, ordered_roster.clone())
                .expect("persist proof-valid TLE key B");
            state_transaction
                .world
                .activate_tle_key_session(key_b_id, current_height, policy)
                .expect("schedule an atomic next-height cutover to TLE key B");

            super::validated_active_parliament_tle_key_session_for_new_ballot_v1(
                key_a_id,
                &state_transaction,
            )
            .expect("predecessor A remains selectable through the cutover height");
            let next_height = current_height.checked_add(1).expect("test height advances");
            assert_eq!(
                state_transaction
                    .world
                    .selectable_tle_key_session_for_fresh_ballot_at(next_height),
                Some(key_b_id),
                "successor B becomes selectable exactly at H + 1"
            );

            let successor_roster = (0..4)
                .map(|_| iroha_model_base::peer::PeerId::new(checked_keypair().public_key().clone()))
                .collect::<Vec<_>>();
            *state_transaction.commit_topology.get_mut() = successor_roster;
            let stale_roster_error =
                super::validated_active_parliament_tle_key_session_for_new_ballot_v1(
                    key_a_id,
                    &state_transaction,
                )
                .expect_err("a topology change must make active key A ineligible for new ballots");
            assert!(
                format!("{stale_roster_error:?}")
                    .contains("not bound to the current commit topology"),
                "unexpected stale-roster rejection: {stale_roster_error:?}"
            );

            let seven_peer_roster = (0..7)
                .map(|_| iroha_model_base::peer::PeerId::new(checked_keypair().public_key().clone()))
                .collect::<Vec<_>>();
            let seven_peer_roster_hash =
                crate::beacon::global_threshold_beacon_roster_hash_v1(&seven_peer_roster);
            let key_c = crate::tle_release::tests::public_key_session_fixture_for_context_v1(
                *state_transaction.network_id.as_bytes(),
                0xC1,
                seven_peer_roster_hash,
            );
            let key_c_id = key_c.key_session_id;
            let mismatched_roster_error = state_transaction
                .world
                .put_tle_key_session(key_c, seven_peer_roster)
                .expect_err("a committee-size mismatch must reject the frozen roster binding");
            assert_eq!(
                mismatched_roster_error,
                crate::tle_release::TleReleaseAdapterError::TranscriptMismatch
            );
            assert!(
                state_transaction
                    .world
                    .tle_key_sessions()
                    .get(&key_c_id)
                    .is_none(),
                "a rejected pair must not leave a partial public session"
            );
            assert!(
                state_transaction
                    .world
                    .tle_key_session_rosters()
                    .get(&key_c_id)
                    .is_none(),
                "a rejected pair must not leave a partial roster binding"
            );

            super::validated_parliament_tle_key_session_v1(key_a_id, &state_transaction)
                .expect("already-bound openings must retain proof-valid access to key A");
            super::validated_parliament_tle_key_session_v1(key_b_id, &state_transaction)
                .expect("already-bound openings must retain proof-valid access to stale key B");
            assert!(state_transaction.world.tle_key_sessions.get(&key_a_id).is_some());
        });

