        fn bridge_proof_hash_for_test(proof: &BridgeProof) -> [u8; 32] {
            let encoded =
                encode_bridge_proof_identity(proof).expect("bridge proof fixture must encode");
            hash_bridge_proof(&proof.backend_label(), &encoded)
        }
        world_test!(bridge_proof_identity_encoding_ignores_ambient_norito_layout {
            let proof = bridge_proof_fixture(4);
            let canonical =
                encode_bridge_proof_identity(&proof).expect("encode canonical bridge proof");
            let canonical_hash = hash_bridge_proof(&proof.backend_label(), &canonical);
            let alternate_flags =
                norito::core::default_encode_flags() ^ norito::core::header_flags::COMPACT_LEN;
            let alternate = {
                let _alternate = norito::core::DecodeFlagsGuard::enter(alternate_flags);
                norito::to_bytes(&proof).expect("encode alternate-layout bridge proof")
            };
            assert_ne!(
                alternate, canonical,
                "fixture must exercise a distinct advertised Norito layout"
            );
            let (ambient_encoded, ambient_hash) = {
                let _ambient = norito::core::DecodeFlagsGuard::enter(alternate_flags);
                let encoded = encode_bridge_proof_identity(&proof)
                    .expect("canonical bridge identity encoding under ambient flags");
                let hash = hash_bridge_proof(&proof.backend_label(), &encoded);
                (encoded, hash)
            };
            assert_eq!(ambient_encoded, canonical);
            assert_eq!(ambient_hash, canonical_hash);
        });
        fn seed_generic_bridge_proof_for_receipt_test(
            stx: &mut StateTransaction<'_, '_>,
            seed: u8,
        ) -> (BridgeProof, [u8; 32]) {
            let proof = bridge_proof_fixture(seed);
            let proof_hash = bridge_proof_hash_for_test(&proof);
            let backend = proof.backend_label();
            let size_bytes = norito::to_bytes(&proof)
                .expect("generic bridge proof fixture should encode")
                .len();
            let id = iroha_data_model::proof::ProofId {
                backend,
                proof_hash,
            };
            stx.world
                .insert_proof_record(iroha_data_model::proof::ProofRecord {
                    id,
                    vk_ref: None,
                    vk_commitment: None,
                    status: iroha_data_model::proof::ProofStatus::Verified,
                    verified_at_height: Some(stx._curr_block.height.get()),
                    bridge: Some(iroha_data_model::bridge::BridgeProofRecord {
                        proof: proof.clone(),
                        commitment: proof_hash,
                        size_bytes: u32::try_from(size_bytes).unwrap_or(u32::MAX),
                    }),
                });
            // Generic proofs cannot be submitted in production. This test-only
            // seed models a pre-existing verified record so receipt invariants
            // can be exercised independently from proof admission.
            stx.bridge_receipt_proofs_available_in_tx.insert(proof_hash);
            assert_contains!(stx.bridge_receipt_proofs_available_in_tx, &proof_hash);
            (proof, proof_hash)
        }
