        fn smart_contract_instruction_error_message(err: InstructionExecutionError) -> String {
            match err {
                InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(msg),
                ) => msg,
                InstructionExecutionError::InvariantViolation(msg) => msg.to_string(),
                other => panic!("unexpected error: {other:?}"),
            }
        }
        fn smart_contract_error_message(err: ValidationFail) -> String {
            match err {
                ValidationFail::InstructionFailed(inner) => {
                    smart_contract_instruction_error_message(inner)
                }
                other => panic!("unexpected error: {other:?}"),
            }
        }
        // Registry shape/codec tests exercise the Core handler with its exact grant.
        // This component boundary is separate from Initial-executor admission: a grant
        // never creates the governed post-genesis lifecycle which the executor requires.
        fn execute_vk_component_fixture(
            state_transaction: &mut StateTransaction<'_, '_>,
            authority: &AccountId,
            instruction: InstructionBox,
        ) -> Result<(), ValidationFail> {
            if let Some(value) = instruction
                .as_any()
                .downcast_ref::<verifying_keys::RegisterVerifyingKey>()
            {
                value.clone().execute(authority, state_transaction)
            } else if let Some(value) = instruction
                .as_any()
                .downcast_ref::<verifying_keys::UpdateVerifyingKey>()
            {
                value.clone().execute(authority, state_transaction)
            } else {
                panic!("the registry component fixture cannot replace another admission owner")
            }
            .map_err(ValidationFail::InstructionFailed)
        }
